1	import React, { useCallback, useEffect, useRef, useState } from "react";
2	import {
3	  Button,
4	  Dialog,
5	  Icon,
6	  NonIdealState,
7	  Spinner,
8	  SpinnerSize,
9	  Tag,
10	} from "@blueprintjs/core";
11	import posthog from "posthog-js";
12	import { render as renderToast } from "roamjs-components/components/Toast";
13	import getPageTitleByPageUid from "roamjs-components/queries/getPageTitleByPageUid";
14	import renderOverlay, {
15	  RoamOverlayProps,
16	} from "roamjs-components/util/renderOverlay";
17	import {
18	  insertPageRefAtRange,
19	  snapshotInsertTarget,
20	  type InsertTarget,
21	} from "~/utils/advancedSearchFooterUtils";
22	import { DiscourseNodeSortControl } from "~/components/DiscourseNodeSortControl";
23	import { getCandidateTagTitle } from "~/utils/discourseNodeSearch";
24	import getDiscourseNodes, {
25	  type DiscourseNode,
26	} from "~/utils/getDiscourseNodes";
27	import { getNodeTagStyles } from "~/utils/getDiscourseNodeColors";
28	import { mountAdvancedSearchInSidebar } from "./mountAdvancedSearchInSidebar";
29	import {
30	  DEBOUNCE_MS,
31	  DEFAULT_SORT_CONFIG,
32	  type SearchResult,
33	  type SortConfig,
34	  buildSearchIndex,
35	  formatBadgeText,
36	  formatMetadataDate,
37	  getSearchKeywords,
38	  splitWithHighlights,
39	  stripTypePrefix,
40	} from "./utils";
41	import { DiscourseNodeTypeFilter } from "~/components/AdvancedNodeSearchDialog/DiscourseNodeTypeFilter";
42	import { RenderRoamBlock, RenderRoamPage } from "~/utils/roamReactComponents";
43	import { AdvancedSearchFooter } from "./AdvancedSearchFooter";
44	import { DisplayOptionsMenu } from "./DisplayOptionsMenu";
45	import { NodeTypeChipsSearchInput } from "./NodeTypeChipsSearchInput";
46	import {
47	  type SearchIndex,
48	  useAdvancedNodeSearchResults,
49	} from "./useAdvancedNodeSearchResults";
50	
51	type Props = Record<string, unknown>;
52	
53	const getNodeBadgeText = (node: DiscourseNode): string => {
54	  return formatBadgeText(node.tag?.trim() || node.text);
55	};
56	
57	const getTagStyle = ({
58	  isCandidate,
59	  node,
60	}: {
61	  isCandidate?: boolean;
62	  node: DiscourseNode | undefined;
63	}): React.CSSProperties => {
64	  const color = node?.canvasSettings?.color;
65	  if (!color) return { flexShrink: 0 };
66	  return {
67	    ...getNodeTagStyles(color),
68	    ...(isCandidate && { backgroundColor: "transparent", boxShadow: "none" }),
69	    flexShrink: 0,
70	  };
71	};
72	
73	// Mirrors Obsidian's "#tag · note · line" line under a candidate's title.
74	const getCandidateSubtitle = ({
75	  candidate,
76	  nodeConfigByType,
77	}: {
78	  candidate: NonNullable<SearchResult["candidate"]>;
79	  nodeConfigByType: Record<string, DiscourseNode>;
80	}): string => {
81	  const tags = candidate.nodeTypes
82	    .map((type) => nodeConfigByType[type]?.tag)
83	    .filter((tag): tag is string => !!tag?.trim())
84	    .map((tag) => `#${getCandidateTagTitle(tag)}`);
85	  return [tags.join(" "), candidate.pageTitle].filter(Boolean).join(" · ");
86	};
87	
88	const renderHighlightedText = (
89	  text: string,
90	  keywords: string[],
91	): React.ReactNode =>
92	  splitWithHighlights(text, keywords).map((segment, index) =>
93	    segment.isMatch ? (
94	      <mark key={`${segment.text}-${index}`}>{segment.text}</mark>
95	    ) : (
96	      <React.Fragment key={`${segment.text}-${index}`}>
97	        {segment.text}
98	      </React.Fragment>
99	    ),
100	  );
101	
102	const ResultRow = ({
103	  active,
104	  keywords,
105	  nodeConfig,
106	  onClick,
107	  onMouseEnter,
108	  result,
109	  subtitle,
110	}: {
111	  active: boolean;
112	  keywords: string[];
113	  nodeConfig: DiscourseNode | undefined;
114	  onClick: () => void;
115	  onMouseEnter: () => void;
116	  result: SearchResult;
117	  subtitle?: string;
118	}) => (
119	  <Button
120	    alignText="left"
121	    aria-selected={active}
122	    className="flex-none !items-start !px-3 !py-2"
123	    fill
124	    minimal
125	    onClick={onClick}
126	    onMouseEnter={onMouseEnter}
127	    role="option"
128	    style={{
129	      background: active ? "rgba(167, 182, 194, 0.3)" : undefined,
130	      boxShadow: active ? "inset 3px 0 0 rgba(167, 182, 194, 0.3)" : undefined,
131	    }}
132	  >
133	    {/* Blueprint wraps children in a block .bp3-button-text span, so this span is the row. */}
134	    <span className="flex min-w-0 items-start gap-2">
135	      <Tag
136	        aria-label={
137	          result.candidate
138	            ? `${nodeConfig?.text ?? result.nodeTypeLabel} candidate`
139	            : undefined
140	        }
141	        minimal
142	        style={getTagStyle({
143	          isCandidate: !!result.candidate,
144	          node: nodeConfig,
145	        })}
146	      >
147	        {nodeConfig
148	          ? getNodeBadgeText(nodeConfig)
149	          : formatBadgeText(result.nodeTypeLabel)}
150	      </Tag>
151	      <span className="flex min-w-0 flex-col">
152	        <span className="break-words text-sm leading-snug text-gray-900">
153	          {renderHighlightedText(stripTypePrefix(result.title), keywords)}
154	        </span>
155	        {subtitle && (
156	          <span className="truncate text-xs text-gray-500">{subtitle}</span>
157	        )}
158	      </span>
159	    </span>
160	  </Button>
161	);
162	
163	const PreviewPane = ({ result }: { result: SearchResult | null }) => {
164	  if (!result) {
165	    return (
166	      <div className="flex min-h-0 flex-1 items-center justify-center overflow-hidden">
167	        <NonIdealState
168	          icon="search"
169	          title="Search DG nodes"
170	          description="Type a keyword to preview matching discourse graph nodes."
171	        />
172	      </div>
173	    );
174	  }
175	  const isPage = !!getPageTitleByPageUid(result.uid);
176	
177	  return (
178	    <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
179	      <div className="flex-none flex-row gap-2 border-b border-gray-200 px-5 py-3 text-xs text-gray-500">
180	        Created: {formatMetadataDate(result.createdAt)} · Last modified:{" "}
181	        {formatMetadataDate(result.lastModified)} · Author:{" "}
182	        {result.authorName || "Unknown"}
183	      </div>
184	      <div
185	        className="min-h-0 flex-1 overflow-y-auto border-t border-gray-200 px-5 py-3"
186	        onMouseDown={(event) => event.preventDefault()}
187	      >
188	        <div className="pointer-events-none">
189	          {isPage ? (
190	            <RenderRoamPage hideMentions key={result.uid} uid={result.uid} />
191	          ) : (
192	            <RenderRoamBlock key={result.uid} uid={result.uid} zoomPath />
193	          )}
194	        </div>
195	      </div>
196	    </div>
197	  );
198	};
199	
200	const AdvancedNodeSearchDialog = ({
201	  isOpen,
202	  onClose,
203	}: RoamOverlayProps<Props>) => {
204	  const [searchTerm, setSearchTerm] = useState("");
205	  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
206	  const [isIndexLoading, setIsIndexLoading] = useState(false);
207	  const [indexError, setIndexError] = useState(false);
208	  const [activeIndex, setActiveIndex] = useState(0);
209	  const [searchIndex, setSearchIndex] = useState<SearchIndex | null>(null);
210	  const [sort, setSort] = useState<SortConfig>(DEFAULT_SORT_CONFIG);
211	  const [discourseNodes, setDiscourseNodes] = useState<DiscourseNode[]>([]);
212	  const [selectedNodeTypeIds, setSelectedNodeTypeIds] = useState<string[]>([]);
213	  const [isTypeFilterPopoverOpen, setIsTypeFilterPopoverOpen] = useState(false);
214	  const [showCandidates, setShowCandidates] = useState(false);
215	  const [isDisplayOptionsOpen, setIsDisplayOptionsOpen] = useState(false);
216	  const resultsPanelRef = useRef<HTMLDivElement | null>(null);
217	  const inputRef = useRef<HTMLInputElement | null>(null);
218	  const [insertTarget, setInsertTarget] = useState<InsertTarget | null>(null);
219	
220	  const nodeConfigByType = Object.fromEntries(
221	    discourseNodes.map((node) => [node.type, node]),
222	  );
223	
224	  const { results, isSearching } = useAdvancedNodeSearchResults({
225	    debouncedSearchTerm,
226	    selectedNodeTypeIds,
227	    sort,
228	    isIndexLoading,
229	    indexError,
230	    searchIndex,
231	  });
232	
233	  const activeResult = results[activeIndex] ?? null;
234	  const keywords = getSearchKeywords(debouncedSearchTerm);
235	
236	  useEffect(() => {
237	    if (!isOpen) return;
238	
239	    setInsertTarget(snapshotInsertTarget());
240	
241	    const focusInput = () => inputRef.current?.focus();
242	
243	    focusInput();
244	    const rafId = requestAnimationFrame(focusInput);
245	    const timeoutId = window.setTimeout(focusInput, 0);
246	
247	    return () => {
248	      cancelAnimationFrame(rafId);
249	      window.clearTimeout(timeoutId);
250	    };
251	  }, [isOpen]);
252	
253	  useEffect(() => {
254	    if (!isOpen) {
255	      setSearchTerm("");
256	      setDebouncedSearchTerm("");
257	      setActiveIndex(0);
258	      setSort(DEFAULT_SORT_CONFIG);
259	      setSelectedNodeTypeIds([]);
260	      setShowCandidates(false);
261	      setIsDisplayOptionsOpen(false);
262	      setSearchIndex(null);
263	      setIndexError(false);
264	    }
265	  }, [isOpen]);
266	
267	  useEffect(() => {
268	    let cancelled = false;
269	    setIsIndexLoading(true);
270	    setIndexError(false);
271	    setSearchIndex(null);
272	
273	    const discourseNodes = getDiscourseNodes().filter(
274	      (node) => node.backedBy === "user",
275	    );
276	    setDiscourseNodes(discourseNodes);
277	
278	    void buildSearchIndex({ discourseNodes, includeCandidates: showCandidates })
279	      .then(({ miniSearch, results: indexedResults }) => {
280	        if (cancelled) return;
281	        setSearchIndex({ miniSearch, allResults: indexedResults });
282	      })
283	      .catch((error) => {
284	        console.error("Error building advanced node search index:", error);
285	        if (cancelled) return;
286	        setIndexError(true);
287	        renderToast({
288	          id: "advanced-node-search-index-error",
289	          content: "Failed to load discourse nodes for search.",
290	          intent: "danger",
291	        });
292	      })
293	      .finally(() => {
294	        if (!cancelled) setIsIndexLoading(false);
295	      });
296	
297	    return () => {
298	      cancelled = true;
299	    };
300	  }, [isOpen, showCandidates]);
301	
302	  useEffect(() => {
303	    const timeout = setTimeout(
304	      () => setDebouncedSearchTerm(searchTerm.trim()),
305	      DEBOUNCE_MS,
306	    );
307	    return () => clearTimeout(timeout);
308	  }, [searchTerm]);
309	
310	  useEffect(() => {
311	    setActiveIndex(0);
312	  }, [debouncedSearchTerm, selectedNodeTypeIds, showCandidates, sort]);
313	
314	  useEffect(() => {
315	    const panel = resultsPanelRef.current;
316	    if (!panel) return;
317	
318	    const activeRow = panel.querySelector('[aria-selected="true"]');
319	    activeRow?.scrollIntoView({ block: "nearest" });
320	  }, [activeIndex, activeResult?.uid, debouncedSearchTerm]);
321	
322	  const onInsert = useCallback(async () => {
323	    if (!activeResult || activeResult.candidate || !insertTarget) return;
324	
325	    const pageTitle =
326	      getPageTitleByPageUid(activeResult.uid) ??
327	      stripTypePrefix(activeResult.title);
328	
329	    await insertPageRefAtRange({
330	      blockUid: insertTarget.blockUid,
331	      pageTitle,
332	      selectionEnd: insertTarget.selectionEnd,
333	      selectionStart: insertTarget.selectionStart,
334	      windowId: insertTarget.windowId,
335	    });
336	
337	    posthog.capture("Advanced Node Search: Insert", {
338	      uid: activeResult.uid,
339	      pageTitle,
340	    });
341	    onClose();
342	  }, [activeResult, insertTarget, onClose]);
343	
344	  const contentState = indexError
345	    ? "error"
346	    : isIndexLoading || isSearching
347	      ? "indexing"
348	      : !debouncedSearchTerm && selectedNodeTypeIds.length === 0
349	        ? "initial"
350	        : !results.length
351	          ? "empty"
352	          : "results";
353	
354	  const onOpenSearchSidebar = useCallback(async () => {
355	    if (contentState !== "results" || !results.length) return;
356	
357	    try {
358	      await mountAdvancedSearchInSidebar({
359	        query: debouncedSearchTerm,
360	        results,
361	        selectedNodeTypeIds,
362	        sort,
363	        showCandidates,
364	      });
365	
366	      posthog.capture("Advanced Node Search: Dock search sidebar", {
367	        resultCount: results.length,
368	        searchTerm: debouncedSearchTerm,
369	        selectedNodeTypeCount: selectedNodeTypeIds.length,
370	        sortDirection: sort.direction,
371	        sortField: sort.field,
372	      });
373	      onClose();
374	    } catch (error) {
375	      console.error("Failed to dock search results in the sidebar:", error);
376	      renderToast({
377	        id: "advanced-node-search-sidebar-open-error",
378	        content: "Could not dock search results in the right sidebar.",
379	        intent: "danger",
380	      });
381	    }
382	  }, [
383	    contentState,
384	    debouncedSearchTerm,
385	    onClose,
386	    results,
387	    selectedNodeTypeIds,
388	    showCandidates,
389	    sort,
390	  ]);
391	  const handleSortChange = useCallback((nextSort: SortConfig): void => {
392	    setSort(nextSort);
393	  }, []);
394	
395	  const onOpen = useCallback(async () => {
396	    if (!activeResult || contentState !== "results") return;
397	
398	    const uid = activeResult.uid;
399	    if (getPageTitleByPageUid(uid)) {
400	      await window.roamAlphaAPI.ui.mainWindow.openPage({ page: { uid } });
401	    } else {
402	      await window.roamAlphaAPI.ui.mainWindow.openBlock({ block: { uid } });
403	    }
404	    onClose();
405	  }, [activeResult, contentState, onClose]);
406	
407	  const onOpenInSidebar = useCallback(async () => {
408	    if (!activeResult || contentState !== "results") return;
409	
410	    await window.roamAlphaAPI.ui.rightSidebar.addWindow({
411	      window: {
412	        type: "outline",
413	        // @ts-expect-error - block-uid is valid for outline sidebar windows
414	        // eslint-disable-next-line @typescript-eslint/naming-convention
415	        "block-uid": activeResult.uid,
416	      },
417	    });
418	    onClose();
419	  }, [activeResult, contentState, onClose]);
420	
421	  const handleSearchKeyDown = useCallback(
422	    (event: React.KeyboardEvent): void => {
423	      if (event.key === "ArrowDown" && results.length) {
424	        event.preventDefault();
425	        setActiveIndex((index) =>
426	          Math.min(Math.max(index, 0) + 1, results.length - 1),
427	        );
428	        return;
429	      }
430	      if (event.key === "ArrowUp" && results.length) {
431	        event.preventDefault();
432	        setActiveIndex((index) => Math.max(index - 1, 0));
433	        return;
434	      }
435	      if (
436	        event.key === "Enter" &&
437	        event.altKey &&
438	        contentState === "results" &&
439	        results.length
440	      ) {
441	        event.preventDefault();
442	        void onOpenSearchSidebar();
443	      } else if (
444	        event.key === "Enter" &&
445	        !event.metaKey &&
446	        !event.ctrlKey &&
447	        contentState === "results" &&
448	        activeResult
449	      ) {
450	        event.preventDefault();
451	        if (event.shiftKey) void onOpenInSidebar();
452	        else void onOpen();
453	        return;
454	      }
455	      if (
456	        event.key === "Enter" &&
457	        (event.metaKey || event.ctrlKey) &&
458	        contentState === "results" &&
459	        activeResult &&
460	        !activeResult.candidate &&
461	        insertTarget
462	      ) {
463	        event.preventDefault();
464	        void onInsert();
465	        return;
466	      }
467	      if (event.key === "Escape") {
468	        if (isTypeFilterPopoverOpen) return;
469	        if (isDisplayOptionsOpen) {
470	          event.preventDefault();
471	          event.stopPropagation();
472	          setIsDisplayOptionsOpen(false);
473	          return;
474	        }
475	        event.preventDefault();
476	        onClose();
477	      }
478	    },
479	    [
480	      activeResult,
481	      contentState,
482	      isDisplayOptionsOpen,
483	      isTypeFilterPopoverOpen,
484	      insertTarget,
485	      onClose,
486	      onOpenSearchSidebar,
487	      onInsert,
488	      onOpen,
489	      onOpenInSidebar,
490	      results.length,
491	    ],
492	  );
493	
494	  const onKeyDown = useCallback(
495	    (event: React.KeyboardEvent<HTMLDivElement>) => {
496	      if (event.defaultPrevented) return;
497	      handleSearchKeyDown(event);
498	    },
499	    [handleSearchKeyDown],
500	  );
501	
502	  const showSplitView = contentState === "results";
503	
504	  return (
505	    <Dialog
506	      autoFocus={false}
507	      canEscapeKeyClose
508	      canOutsideClickClose
509	      className="flex w-full max-w-4xl flex-col overflow-hidden bg-white p-0"
510	      enforceFocus={false}
511	      isOpen={isOpen}
512	      onClose={onClose}
513	      style={{
514	        height: "72vh",
515	        width: "min(56rem, calc(100vw - 64px))",
516	      }}
517	    >
518	      <div
519	        onClick={(event) => event.stopPropagation()}
520	        onKeyDown={onKeyDown}
521	        onMouseDown={(event) => event.stopPropagation()}
522	        onMouseUp={(event) => event.stopPropagation()}
523	        className="flex min-h-0 flex-1 flex-col overflow-hidden"
524	      >
525	        <div className="flex w-full flex-none items-start gap-2 border-b border-gray-200 px-3 py-2">
526	          <div className="flex min-h-9 min-w-0 flex-1 items-center rounded border border-gray-300 bg-white px-2 py-1">
527	            <Icon
528	              className="mr-2 shrink-0 self-center text-gray-500"
529	              icon="search"
530	              size={16}
531	            />
532	            <NodeTypeChipsSearchInput
533	              inputRef={inputRef}
534	              nodeTypes={discourseNodes}
535	              onSearchKeyDown={handleSearchKeyDown}
536	              onSearchTermChange={setSearchTerm}
537	              onSelectedTypeIdsChange={setSelectedNodeTypeIds}
538	              searchTerm={searchTerm}
539	              selectedTypeIds={selectedNodeTypeIds}
540	            />
541	          </div>
542	          <DiscourseNodeTypeFilter
543	            layoutAnchorKey={selectedNodeTypeIds.length}
544	            nodeTypes={discourseNodes}
545	            onPopoverOpenChange={setIsTypeFilterPopoverOpen}
546	            onSelectedTypeIdsChange={setSelectedNodeTypeIds}
547	            selectedTypeIds={selectedNodeTypeIds}
548	          />
549	          <DiscourseNodeSortControl
550	            disabled={isIndexLoading || indexError}
551	            onSortChange={handleSortChange}
552	            sort={sort}
553	          />
554	          <DisplayOptionsMenu
555	            isOpen={isDisplayOptionsOpen}
556	            onOpenChange={setIsDisplayOptionsOpen}
557	            onShowCandidatesChange={setShowCandidates}
558	            showCandidates={showCandidates}
559	          />
560	          <Button
561	            className="shrink-0"
562	            icon="cross"
563	            minimal
564	            onClick={onClose}
565	            title="Close search"
566	          />
567	        </div>
568	        <div className="flex min-h-0 w-full flex-1 overflow-hidden">
569	          {showSplitView ? (
570	            <>
571	              <div
572	                aria-label="Search results"
573	                className="w-1/3 shrink-0 overflow-y-auto border-r border-gray-200 py-1"
574	                ref={resultsPanelRef}
575	                role="listbox"
576	              >
577	                {results.map((result, index) => (
578	                  <ResultRow
579	                    active={index === activeIndex}
580	                    key={result.uid}
581	                    keywords={keywords}
582	                    nodeConfig={nodeConfigByType[result.type]}
583	                    onClick={() => setActiveIndex(index)}
584	                    onMouseEnter={() => setActiveIndex(index)}
585	                    result={result}
586	                    subtitle={
587	                      result.candidate &&
588	                      getCandidateSubtitle({
589	                        candidate: result.candidate,
590	                        nodeConfigByType,
591	                      })
592	                    }
593	                  />
594	                ))}
595	              </div>
596	              <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden">
597	                <PreviewPane result={activeResult} />
598	              </div>
599	            </>
600	          ) : (
601	            <div className="flex min-h-0 w-full flex-1 items-center justify-center px-4 py-8 text-center text-sm text-gray-500">
602	              {contentState === "indexing" && (
603	                <Spinner size={SpinnerSize.SMALL} />
604	              )}
605	              {contentState === "empty" && (
606	                <span>No matches. Try another keyword or filter.</span>
607	              )}
608	              {contentState === "error" && (
609	                <span>
610	                  Search unavailable. Reload the extension and try again.
611	                </span>
