92	export const splitWithHighlights = (
93	  text: string,
94	  keywords: string[],
95	): { text: string; isMatch: boolean }[] => {
96	  if (!keywords.length) return [{ text, isMatch: false }];
97	
98	  const escapedKeywords = keywords.map((keyword) =>
99	    keyword.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
100	  );
101	  const regex = new RegExp(`(${escapedKeywords.join("|")})`, "gi");
102	  const loweredKeywords = new Set(
103	    keywords.map((keyword) => keyword.toLowerCase()),
104	  );
105	
106	  return text
107	    .split(regex)
108	    .filter(Boolean)
109	    .map((part) => ({
110	      text: part,
111	      isMatch: loweredKeywords.has(part.toLowerCase()),
112	    }));
113	};
