215	export const buildSearchIndex = async ({
216	  discourseNodes,
217	  includeCandidates = false,
218	}: {
219	  discourseNodes: DiscourseNode[];
220	  includeCandidates?: boolean;
221	}): Promise<{
222	  miniSearch: MiniSearch<MiniSearchDocument>;
223	  results: SearchResult[];
224	}> => {
225	  const [resultsByType, candidatesByType] = await Promise.all([
226	    Promise.allSettled(discourseNodes.map(queryNodesForType)),
227	    includeCandidates ? queryCandidates(discourseNodes) : [],
228	  ]);
229	
230	  const rejected = resultsByType.filter(
231	    (result): result is PromiseRejectedResult => result.status === "rejected",
232	  );
233	  if (discourseNodes.length > 0 && rejected.length === discourseNodes.length) {
234	    throw (
235	      rejected[0]?.reason ??
236	      new Error("Failed to build advanced node search index")
237	    );
238	  }
239	
240	  // Candidates come after nodes. A block tagged with several types is one row
241	  // shown as the first configured type, and type filters match any of its tags.
242	  const results: SearchResult[] = [];
243	  const resultsByUid = new Map<string, SearchResult>();
244	  for (const resultByType of [...resultsByType, ...candidatesByType]) {
245	    if (resultByType.status !== "fulfilled") continue;
246	    for (const result of resultByType.value) {
247	      const existing = resultsByUid.get(result.uid);
248	      if (existing) {
249	        if (existing.candidate && result.candidate) {
250	          existing.candidate.nodeTypes.push(...result.candidate.nodeTypes);
251	        }
252	        continue;
253	      }
254	      resultsByUid.set(result.uid, result);
255	      results.push(result);
256	    }
257	  }
258	
259	  const miniSearch = new MiniSearch<MiniSearchDocument>({
260	    fields: ["title", "nodeTypeLabel"],
261	    storeFields: ["uid", "title", "type", "nodeTypeLabel", "excerpt"],
262	    idField: "id",
263	  });
264	
265	  miniSearch.addAll(results.map((result) => ({ ...result, id: result.uid })));
266	
267	  return { miniSearch, results };
268	};
