270	const compareNumbers = (
271	  a: number,
272	  b: number,
273	  direction: SortDirection,
274	): number => (direction === "desc" ? b - a : a - b);
275	
276	const compareStrings = (
277	  a: string,
278	  b: string,
279	  direction: SortDirection,
280	): number => {
281	  const comparison = a.localeCompare(b, undefined, { sensitivity: "base" });
282	  return direction === "desc" ? -comparison : comparison;
283	};
284	
285	const getSortableTitle = (result: SearchResult): string =>
286	  stripTypePrefix(result.title);
287	
288	const getCreatedTime = (result: SearchResult): number =>
289	  Number(result.createdAt) || 0;
290	
291	export const isNonDefaultSort = (sort: SortConfig): boolean =>
292	  sort.field !== DEFAULT_SORT_CONFIG.field ||
293	  sort.direction !== DEFAULT_SORT_CONFIG.direction;
294	
295	export const sortSearchResults = ({
296	  scoredResults,
297	  sort,
298	}: {
299	  scoredResults: ScoredSearchResult[];
300	  sort: SortConfig;
301	}): SearchResult[] => {
302	  // Semantic and MiniSearch results already arrive in their provider's relevance
303	  // order, so relevance sorting only has to reverse it for ascending.
304	  if (sort.field === "relevance") {
305	    const ordered =
306	      sort.direction === "asc" ? [...scoredResults].reverse() : scoredResults;
307	    return ordered.map((entry) => entry.result);
308	  }
309	
310	  const sorted = [...scoredResults];
311	
312	  sorted.sort((aEntry, bEntry) => {
313	    const a = aEntry.result;
314	    const b = bEntry.result;
315	    let comparison = 0;
316	
317	    switch (sort.field) {
318	      case "alphabetical":
319	        comparison = compareStrings(
320	          getSortableTitle(a),
321	          getSortableTitle(b),
322	          sort.direction,
323	        );
324	        break;
325	      case "dateCreated":
326	        comparison = compareNumbers(
327	          getCreatedTime(a),
328	          getCreatedTime(b),
329	          sort.direction,
330	        );
331	        break;
332	      case "author": {
333	        const aAuthor = a.authorName.trim();
334	        const bAuthor = b.authorName.trim();
335	        if (!aAuthor && !bAuthor) comparison = 0;
336	        else if (!aAuthor) comparison = 1;
337	        else if (!bAuthor) comparison = -1;
338	        else comparison = compareStrings(aAuthor, bAuthor, sort.direction);
339	        break;
340	      }
341	    }
342	
343	    return comparison || a.uid.localeCompare(b.uid);
344	  });
345	
346	  return sorted.map((entry) => entry.result);
347	};
348	
349	export const matchesTypeFilter = (
350	  result: SearchResult,
351	  allowedTypes: Set<string>,
352	): boolean =>
353	  allowedTypes.has(result.type) ||
354	  !!result.candidate?.nodeTypes.some((type) => allowedTypes.has(type));
355	
356	export const searchDiscourseNodesWithMiniSearch = ({
357	  miniSearch,
358	  allResults,
359	  searchTerm,
360	  typeFilter,
361	}: {
362	  miniSearch: MiniSearch<MiniSearchDocument>;
363	  allResults: SearchResult[];
364	  searchTerm: string;
365	  typeFilter?: string[];
366	}): ScoredSearchResult[] => {
367	  const resultsByUid = new Map(
368	    allResults.map((result) => [result.uid, result]),
369	  );
370	  const allowedTypes = typeFilter?.length ? new Set(typeFilter) : null;
371	
372	  return miniSearch
373	    .search(searchTerm, {
374	      fields: ["title", "nodeTypeLabel"],
375	      ...DISCOURSE_NODE_MINI_SEARCH_OPTIONS,
376	      filter: allowedTypes
377	        ? (result) => {
378	            const searchResult = resultsByUid.get(String(result.id));
379	            return (
380	              !!searchResult && matchesTypeFilter(searchResult, allowedTypes)
381	            );
382	          }
383	        : undefined,
384	    })
385	    .filter((result) => result.score > DISCOURSE_NODE_MIN_SEARCH_SCORE)
386	    .slice(0, MAX_RESULTS)
387	    .map((result) => {
388	      const searchResult = resultsByUid.get(String(result.id));
389	      if (!searchResult) return null;
390	      return {
391	        result: searchResult,
392	        score: result.score,
393	        source: "miniSearch",
394	      };
395	    })
396	    .filter((entry): entry is ScoredSearchResult => !!entry);
397	};
